insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,employment_total,median_hourly_earnings,annualised_median_salary,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values
('IE:carpenter','2026-08-10',null,null,null,15,0,0,0,12,0,0,6,4,37,'career-opportunity-ie-v1','provisional',jsonb_build_object('classification_scope','SOC 2010 5315 Carpenters and joiners.','shortage_basis','SOLAS National Skills Bulletin 2025 identifies Carpenters as a current shortage; 15/20.','visa_basis','Outside the current Ineligible List; General Employment Permit route can apply subject to normal criteria; 6/10.','salary_method','No exact current occupation-level median earnings series is normalised. Construction SEO statutory minimum rates are not treated as median salary; 0/10.','entry_basis','National Carpentry and Joinery craft apprenticeship; 12/15.','entry_burden_basis','No universal professional register; Safe Pass is a separate mandatory site-safety credential; 4/5.'),'2026-08-10'),
('IE:electrician','2026-08-10',null,null,null,8,0,0,0,12,0,0,6,2,28,'career-opportunity-ie-v1','provisional',jsonb_build_object('classification_scope','SOC 2010 5241 Electricians and electrical fitters.','shortage_basis','SOLAS National Skills Bulletin 2025 identifies Electricians as a potential future skills shortage; 8/20.','visa_basis','Outside the current Ineligible List; General Employment Permit route can apply subject to normal criteria; 6/10.','salary_method','No exact current occupation-level median earnings series is normalised; 0/10.','entry_basis','National Electrical craft apprenticeship; 12/15.','entry_burden_basis','Restricted electrical works/electrical contracting are regulated through CRU Safe Electric and require REC scope; 2/5.'),'2026-08-10'),
('IE:plumber','2026-08-10',null,null,null,8,0,0,0,12,0,0,6,3,29,'career-opportunity-ie-v1','provisional',jsonb_build_object('classification_scope','SOC 2010 5314 Plumbers and heating and ventilating engineers.','shortage_basis','SOLAS National Skills Bulletin 2025 identifies Plumbers as a potential future skills shortage; 8/20.','visa_basis','Outside the current Ineligible List; General Employment Permit route can apply subject to normal criteria; 6/10.','salary_method','No exact current occupation-level median earnings series is normalised; 0/10.','entry_basis','National Plumbing craft apprenticeship; 12/15.','entry_burden_basis','General plumbing has no universal register, but regulated gas works require RGI registration; 3/5.'),'2026-08-10'),
('IE:wall-floor-tiler','2026-08-10',null,null,null,0,0,0,0,8,0,0,6,4,18,'career-opportunity-ie-v1','provisional',jsonb_build_object('classification_scope','SOC 2010 5322 Floorers and wall tilers.','shortage_basis','No exact current shortage finding in the SOLAS 2025 construction summary; broader construction demand is not inherited; 0/20.','visa_basis','Outside the current Ineligible List; General Employment Permit route can apply subject to normal criteria; 6/10.','salary_method','No exact current occupation-level median earnings series is normalised; 0/10.','entry_basis','No dedicated exact craft apprenticeship is asserted from the current national apprenticeship directory; trade competence plus site-safety requirements; 8/15.','entry_burden_basis','No universal professional register; Safe Pass applies to construction-site workers; 4/5.'),'2026-08-10'),
('IE:welder','2026-08-10',null,null,null,15,0,0,0,10,0,0,6,4,35,'career-opportunity-ie-v1','provisional',jsonb_build_object('classification_scope','SOC 2010 5215 Welding trades.','shortage_basis','SOLAS National Skills Bulletin 2025 identifies Welders/fabricators as a current shortage; 15/20.','visa_basis','Outside the current Ineligible List; General Employment Permit route can apply subject to normal criteria; 6/10.','salary_method','No exact current occupation-level median earnings series is normalised; 0/10.','entry_basis','Metal Fabrication national craft apprenticeship is retained as a related structured welding pathway, not a one-to-one equivalence; 10/15.','entry_burden_basis','No universal statutory welder register; project/process qualifications and Safe Pass can apply by setting; 4/5.'),'2026-08-10'),
('IE:bricklayer','2026-08-10',null,null,null,0,0,0,0,12,0,0,6,4,22,'career-opportunity-ie-v1','provisional',jsonb_build_object('classification_scope','SOC 2010 5312 Bricklayers and masons.','shortage_basis','No separate exact shortage finding in the SOLAS 2025 construction summary; wider housing pressure is not converted into occupation points; 0/20.','visa_basis','Outside the current Ineligible List; General Employment Permit route can apply subject to normal criteria; 6/10.','salary_method','No exact current occupation-level median earnings series is normalised; 0/10.','entry_basis','National Brick and Stonelaying craft apprenticeship; 12/15.','entry_burden_basis','No universal professional register; Safe Pass applies to construction-site workers; 4/5.'),'2026-08-10'),
('IE:hvac-technician','2026-08-10',null,null,null,0,0,0,0,12,0,0,6,2,20,'career-opportunity-ie-v1','provisional',jsonb_build_object('classification_scope','SOC 2010 5225 Air-conditioning and refrigeration engineers.','shortage_basis','No exact current HVAC shortage finding is asserted from the reviewed SOLAS 2025 summaries; 0/20.','visa_basis','Outside the current Ineligible List; General Employment Permit route can apply subject to normal criteria; 6/10.','salary_method','No exact current occupation-level median earnings series is normalised; 0/10.','entry_basis','National Refrigeration craft apprenticeship; 12/15.','entry_burden_basis','Covered F-gas installation/service/repair/recovery work requires appropriate personnel certification; 2/5.'),'2026-08-10'),
('IE:construction-manager','2026-08-10',null,null,null,15,0,0,0,6,0,0,10,4,35,'career-opportunity-ie-v1','provisional',jsonb_build_object('classification_scope','Primary SOC 2010 2436 Construction project managers and related professionals, with SOC 1122 Site Manager retained as an included management scope.','shortage_basis','SOLAS National Skills Bulletin 2025 identifies Construction project managers as a current shortage; 15/20.','visa_basis','Current Critical Skills Occupations List includes SOC 2436 Construction project managers and SOC 1122 Site Manager; 10/10.','salary_method','No exact current occupation-level median earnings series is normalised; 0/10.','entry_basis','Degree/technical education and substantial construction-project experience are common; no unverified Ireland university programme is published from the current programme cohort; 6/15.','entry_burden_basis','No universal statutory construction-manager register; project/site competence and Safe Pass rules may apply; 4/5.'),'2026-08-10')
